import 'package:flutter/material.dart';
import 'package:get/get.dart';
import 'package:get_it/get_it.dart';
import 'package:domain/modules/auth/use_cases/auth_login_use_case.dart';
import 'package:domain/modules/auth/use_cases/auth_register_use_case.dart';
import 'package:presentation/controllers/controller_imports.dart';
import 'package:presentation/utils/constants/pending_ids.dart';

class AuthController extends GetxController {
  final AuthLoginUseCase _authLoginUseCase = GetIt.instance<AuthLoginUseCase>();
  final AuthRegisterUseCase _authRegisterUseCase = GetIt.instance<AuthRegisterUseCase>();

  final TextEditingController loginEmailController = TextEditingController();
  final TextEditingController loginPasswordController = TextEditingController();
  final TextEditingController registerEmailController = TextEditingController();
  final TextEditingController registerPasswordController = TextEditingController();
  final TextEditingController registerConfirmPasswordController = TextEditingController();

  final RxBool isPasswordVisible = false.obs;

  void toggleVisibilityPassword() {
    isPasswordVisible.toggle();
  }

  Future<void> login({required BuildContext context, VoidCallback? onSuccess}) async {
    final email = loginEmailController.text.trim();
    final password = loginPasswordController.text;

    if (email.isEmpty || password.isEmpty) {
      _showSnack(context, 'Email and password are required.');
      return;
    }

    mainAppController.addPendingIds([PendingIds.login]);
    final result = await _authLoginUseCase(AuthLoginParams(email: email, password: password));
    result.fold(
      (failure) => _showSnack(context, failure.message),
      (_) => onSuccess?.call(),
    );
    mainAppController.removePendingIds([PendingIds.login]);
  }

  Future<void> register({required BuildContext context, VoidCallback? onSuccess}) async {
    final email = registerEmailController.text.trim();
    final password = registerPasswordController.text;
    final confirmPassword = registerConfirmPasswordController.text;

    if (email.isEmpty || password.isEmpty || confirmPassword.isEmpty) {
      _showSnack(context, 'Email and password are required.');
      return;
    }

    if (password != confirmPassword) {
      _showSnack(context, 'Passwords do not match.');
      return;
    }

    mainAppController.addPendingIds([PendingIds.register]);
    final result = await _authRegisterUseCase(AuthRegisterParams(email: email, password: password));
    result.fold(
      (failure) => _showSnack(context, failure.message),
      (_) => onSuccess?.call(),
    );
    mainAppController.removePendingIds([PendingIds.register]);
  }

  void _showSnack(BuildContext context, String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  @override
  void onClose() {
    loginEmailController.dispose();
    loginPasswordController.dispose();
    registerEmailController.dispose();
    registerPasswordController.dispose();
    registerConfirmPasswordController.dispose();
    super.onClose();
  }
}

import 'package:flutter/material.dart';
import 'package:get/get.dart';
import 'package:get_it/get_it.dart';
import 'package:domain/modules/auth/use_cases/auth_login_use_case.dart';
import 'package:domain/modules/auth/use_cases/auth_register_use_case.dart';
import 'package:presentation/controllers/controller_imports.dart';
import 'package:presentation/utils/constants/pending_ids.dart';

class AuthController extends GetxController {
  final AuthLoginUseCase _authLoginUseCase = GetIt.instance<AuthLoginUseCase>();
  final AuthRegisterUseCase _authRegisterUseCase = GetIt.instance<AuthRegisterUseCase>();

  final TextEditingController loginEmailController = TextEditingController();
  final TextEditingController loginPasswordController = TextEditingController();
  final TextEditingController registerEmailController = TextEditingController();
  final TextEditingController registerPasswordController = TextEditingController();
  final TextEditingController registerConfirmPasswordController = TextEditingController();

  final RxBool isPasswordVisible = false.obs;

  final GlobalKey<FormState> loginFormKey = GlobalKey<FormState>();
  final GlobalKey<FormState> registerFormKey = GlobalKey<FormState>();

  final RegExp _emailRegex = RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$');

  void toggleVisibilityPassword() {
    isPasswordVisible.toggle();
  }

  String? validateEmail(String? value) {
    final email = value?.trim() ?? '';
    if (email.isEmpty) {
      return 'Email is required.';
    }
    if (!_emailRegex.hasMatch(email)) {
      return 'Invalid email format.';
    }
    return null;
  }

  String? validatePassword(String? value) {
    final password = value ?? '';
    if (password.isEmpty) {
      return 'Password is required.';
    }
    if (password.length < 6) {
      return 'Password must be at least 6 characters.';
    }
    return null;
  }

  String? validateConfirmPassword(String? value) {
    final confirm = value ?? '';
    if (confirm.isEmpty) {
      return 'Please confirm your password.';
    }
    if (confirm != registerPasswordController.text) {
      return 'Passwords do not match.';
    }
    return null;
  }

  Future<void> login({required BuildContext context, VoidCallback? onSuccess}) async {
    final isValid = loginFormKey.currentState?.validate() ?? false;
    if (!isValid) {
      return;
    }

    final email = loginEmailController.text.trim();
    final password = loginPasswordController.text;

    mainAppController.addPendingIds([PendingIds.login]);
    final result = await _authLoginUseCase(AuthLoginParams(email: email, password: password));
    result.fold(
      (failure) => _showSnack(context, failure.message),
      (_) => onSuccess?.call(),
    );
    mainAppController.removePendingIds([PendingIds.login]);
  }

  Future<void> register({required BuildContext context, VoidCallback? onSuccess}) async {
    final isValid = registerFormKey.currentState?.validate() ?? false;
    if (!isValid) {
      return;
    }

    final email = registerEmailController.text.trim();
    final password = registerPasswordController.text;
    final confirmPassword = registerConfirmPasswordController.text;

    mainAppController.addPendingIds([PendingIds.register]);
    final result = await _authRegisterUseCase(AuthRegisterParams(email: email, password: password));
    result.fold(
      (failure) => _showSnack(context, failure.message),
      (_) => onSuccess?.call(),
    );
    mainAppController.removePendingIds([PendingIds.register]);
  }

  void _showSnack(BuildContext context, String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  @override
  void onClose() {
    loginEmailController.dispose();
    loginPasswordController.dispose();
    registerEmailController.dispose();
    registerPasswordController.dispose();
    registerConfirmPasswordController.dispose();
    super.onClose();
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_screenutil/flutter_screenutil.dart';
import 'package:get/get.dart';
import 'package:presentation/controllers/home_controller.dart';
import 'package:presentation/resources/app_colors.dart';
import 'package:presentation/resources/text_styles.dart';
import 'dart:math' as math;

class HomeTab extends StatefulWidget {
  const HomeTab({super.key});

  @override
  State<HomeTab> createState() => _HomeTabState();
}

class _HomeTabState extends State<HomeTab> with SingleTickerProviderStateMixin {
  late final HomeController _controller;
  late final AnimationController _pulseController;
  late final Animation<double> _pulseAnimation;
  late final Animation<double> _pulseBorderScale;
  late final Animation<double> _pulseBorderOpacity;
  Worker? _recordingWorker;

  @override
  void initState() {
    super.initState();
    _controller = Get.put(HomeController());
    _pulseController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1400),
    );
    _pulseAnimation = Tween<double>(begin: 1.0, end: 1.05).animate(
      CurvedAnimation(parent: _pulseController, curve: Curves.easeInOutSine),
    );
    _pulseBorderScale = Tween<double>(begin: 1.0, end: 1.18).animate(
      CurvedAnimation(parent: _pulseController, curve: Curves.easeOut),
    );
    _pulseBorderOpacity = Tween<double>(begin: 0.45, end: 0.0).animate(
      CurvedAnimation(parent: _pulseController, curve: Curves.easeOut),
    );
    _recordingWorker = ever<bool>(_controller.isRecording, (isRecording) {
      if (isRecording) {
        _pulseController.repeat(reverse: true);
      } else {
        _pulseController.stop();
        _pulseController.value = 0.0;
      }
    });
  }

  @override
  void dispose() {
    _recordingWorker?.dispose();
    _pulseController.dispose();
    super.dispose();
  }

  double _barHeight(double base, double variance, double phase) {
    final t = _pulseController.value * 2 * math.pi;
    return base + variance * (1 + math.sin(t + phase)) / 2;
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: .symmetric(vertical: 16.h, horizontal: 24.w),
      child: Column(
        crossAxisAlignment: .start,
        children: [
          Text('Hi!', style: TextStyles.whiteBold(fontSize: 24.sp)),
          8.verticalSpace,
          Text('How is your car today?', style: TextStyles.baseTextStyle),
          const Spacer(),
          Container(
            padding: .all(60.w),
            decoration: BoxDecoration(
              color: AppColors.onBackground,
              borderRadius: .circular(24.r),
              border: .all(color: AppColors.borderColor),
            ),
            child: Center(
              child: GestureDetector(
                onTap: () => _controller.toggleRecording(context: context),
                child: Stack(
                  alignment: Alignment.center,
                  children: [
                    AnimatedBuilder(
                      animation: _pulseController,
                      builder: (context, _) {
                        return Opacity(
                          opacity: _controller.isRecording.value ? _pulseBorderOpacity.value : 0.0,
                          child: Transform.scale(
                            scale: _pulseBorderScale.value,
                            child: Container(
                              height: 140.w,
                              width: 140.w,
                              decoration: BoxDecoration(
                                shape: BoxShape.circle,
                                border: Border.all(color: AppColors.recordingStart, width: 2),
                              ),
                            ),
                          ),
                        );
                      },
                    ),
                    ScaleTransition(
                      scale: _pulseAnimation,
                      child: Obx(() {
                        final isRecording = _controller.isRecording.value;
                        final gradientColors = isRecording
                            ? const [AppColors.recordingStart, AppColors.recordingEnd]
                            : const [AppColors.primary, AppColors.secondary];
                        return Container(
                          height: 140.w,
                          width: 140.w,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            gradient: LinearGradient(colors: gradientColors),
                            boxShadow: [
                              BoxShadow(
                                color: (isRecording ? AppColors.recordingStart : AppColors.primary)
                                    .withAlpha(100),
                                blurRadius: 6,
                                spreadRadius: 2,
                              ),
                            ],
                          ),
                          child: Center(
                            child: isRecording
                                ? AnimatedBuilder(
                                    animation: _pulseController,
                                    builder: (context, _) {
                                      return SizedBox(
                                        height: 30.w,
                                        child: Row(
                                          mainAxisAlignment: MainAxisAlignment.center,
                                          crossAxisAlignment: CrossAxisAlignment.end,
                                          children: [
                                            _buildBar(_barHeight(18.w, 8.w, 0.0)),
                                            _buildBar(_barHeight(22.w, 10.w, 1.1)),
                                            _buildBar(_barHeight(16.w, 7.w, 2.2)),
                                            _buildBar(_barHeight(20.w, 9.w, 3.3)),
                                          ],
                                        ),
                                      );
                                    },
                                  )
                                : Icon(Icons.mic, size: 60.w, color: AppColors.white),
                          ),
                        );
                      }),
                    ),
                    /*Positioned(
                      top: 6.w,
                      right: 6.w,
                      child: Container(
                        height: 28.w,
                        width: 28.w,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: AppColors.onBackground,
                          border: Border.all(color: AppColors.secondary, width: 1.5),
                        ),
                        child: Icon(Icons.graphic_eq, size: 16.w, color: AppColors.secondary),
                      ),
                    ),*/
                  ],
                ),
              ),
            ),
          ),
          const Spacer(),
        ],
      ),
    );
  }

  Widget _buildBar(double height) {
    return Padding(
      padding: EdgeInsets.symmetric(horizontal: 4.w),
      child: SizedBox(
        height: 60.w,
        child: Align(
          alignment: Alignment.bottomCenter,
          child: Container(
            width: 8.w,
            height: height,
            decoration: BoxDecoration(
              color: AppColors.white,
              borderRadius: BorderRadius.circular(6.r),
            ),
          ),
        ),
      ),
    );
  }
}

